let width,depth,lon0,lat0,scale=.001,cx,cz,time=0;
const v3=(x,y,z)=>new THREE.Vector3(x,y,z);
function xy(lon,lat){return [(lon-lon0)*111320*Math.cos(lat0*Math.PI/180)*scale,-(lat-lat0)*111320*scale]}
function sample(lon,lat){const [w,s,e,n]=meta.bounds;const x=THREE.MathUtils.clamp((lon-w)/(e-w)*(meta.width-1),0,meta.width-1),y=THREE.MathUtils.clamp((n-lat)/(n-s)*(meta.height-1),0,meta.height-1);const a=Math.floor(x),b=Math.floor(y),c=Math.min(a+1,meta.width-1),d=Math.min(b+1,meta.height-1),u=x-a,v=y-b;return (heights[b*meta.width+a]*(1-u)+heights[b*meta.width+c]*u)*(1-v)+(heights[d*meta.width+a]*(1-u)+heights[d*meta.width+c]*u)*v}
function point(lon,lat,lift=.025){const [x,z]=xy(lon,lat);return v3(x,(sample(lon,lat)-meta.min)*scale*12+lift,z)}
function ringContains(p,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if(((a[1]>p[1])!==(b[1]>p[1]))&&(p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0]))inside=!inside}return inside}
