function clear(group){while(group.children.length){const c=group.children[0];group.remove(c);c.geometry?.dispose();if(Array.isArray(c.material))c.material.forEach(m=>m.dispose());else c.material?.dispose()}}
function initScene(){scene=new THREE.Scene();scene.background=new THREE.Color('#e7ece3');world=new THREE.Group();scene.add(world);scene.fog=new THREE.Fog('#e7ece3',40,90);camera=new THREE.PerspectiveCamera(36,1,.02,180);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.9;$('scene').append(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.485;controls.minDistance=1;controls.maxDistance=65;scene.add(new THREE.HemisphereLight(0xf9fff2,0x6f8978,1.5));const sun=new THREE.DirectionalLight(0xfff5d4,2.1);sun.position.set(-12,23,-8);scene.add(sun);const fill=new THREE.DirectionalLight(0xa2dce1,.7);fill.position.set(10,4,8);scene.add(fill);riverGroup=new THREE.Group();boundaryGroup=new THREE.Group();waterGroup=new THREE.Group();baseGroup=new THREE.Group();world.add(riverGroup,boundaryGroup,waterGroup,baseGroup);new ResizeObserver(resize).observe($('viewport'));resize()}
function resize(){if(!renderer)return;const r=$('viewport').getBoundingClientRect();camera.aspect=r.width/r.height;camera.setViewOffset(r.width,r.height,0,r.height*.06,r.width,r.height);camera.updateProjectionMatrix();renderer.setSize(r.width,r.height)}
function buildTerrain(){if(terrain){world.remove(terrain);terrain.geometry.dispose();terrain.material.dispose()}clear(baseGroup);const w=meta.width,h=meta.height;const geometry=new THREE.PlaneGeometry(width,depth,w-1,h-1);geometry.rotateX(-Math.PI/2);const pos=geometry.attributes.position;const colors=new Float32Array(w*h*3);const low=new THREE.Color('#577960'),high=new THREE.Color('#b6b788'),outside=new THREE.Color('#c7cfb8');const [west,south,east,north]=meta.bounds;for(let j=0;j<h;j++){for(let i=0;i<w;i++){const k=j*w+i,alt=heights[k],lon=west+i/(w-1)*(east-west),lat=north-j/(h-1)*(north-south);pos.setY(k,(alt-meta.min)*scale*12);const c=low.clone().lerp(high,Math.pow((alt-meta.min)/(meta.max-meta.min),.8));if(surfaceMask[k]===0)c.lerp(outside,.85);if(surfaceMask[k]===2)c.set('#238b9b');const contour=surfaceMask[k]===2?1:((alt%20)<1.1)? .9:1;c.multiplyScalar(contour);c.toArray(colors,k*3)}}geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));geometry.computeVertexNormals();terrain=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.95,metalness:0,side:THREE.DoubleSide}));world.add(terrain);
// Vertical sides keep the real sampled profile, revealing the terrain block.
const edge=[];for(let i=0;i<w;i++)edge.push(i);for(let j=1;j<h;j++)edge.push(j*w+w-1);for(let i=w-2;i>=0;i--)edge.push((h-1)*w+i);for(let j=h-2;j>=0;j--)edge.push(j*w);const verts=[],col=[];for(let q=0;q<edge.length;q++){const a=edge[q],b=edge[(q+1)%edge.length];const ax=pos.getX(a),az=pos.getZ(a),ay=pos.getY(a),bx=pos.getX(b),bz=pos.getZ(b),by=pos.getY(b);verts.push(ax,ay,az,ax,-.45,az,bx,by,bz,bx,by,bz,ax,-.45,az,bx,-.45,bz);for(let k=0;k<6;k++){const c=new THREE.Color(k===1||k===4||k===5?'#7d8061':'#a7a887');c.toArray(col,col.length)}}const wallGeo=new THREE.BufferGeometry();wallGeo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));wallGeo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));wallGeo.computeVertexNormals();baseGroup.add(new THREE.Mesh(wallGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,side:THREE.DoubleSide})));const plinth=new THREE.Mesh(new THREE.BoxGeometry(width+.1,.15,depth+.1),new THREE.MeshStandardMaterial({color:'#355548',roughness:.7}));plinth.position.y=-.52;baseGroup.add(plinth);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(130,130),new THREE.MeshBasicMaterial({color:'#e7ece3'}));ground.rotation.x=-Math.PI/2;ground.position.y=-.61;baseGroup.add(ground);
}
function buildBoundary(){clear(boundaryGroup);for(const poly of boundary.coordinates)for(const ring of poly){const pts=[];for(let i=1;i<ring.length;i++){const a=ring[i-1],b=ring[i];const n=Math.max(1,Math.ceil(Math.hypot((b[0]-a[0])*62,(b[1]-a[1])*111)/.04));for(let j=0;j<n;j++)pts.push(point(a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n,.028))}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineDashedMaterial({color:'#e2bc78',dashSize:.055,gapSize:.035,transparent:true,opacity:.9}));line.computeLineDistances();boundaryGroup.add(line)}}
function buildWater(){clear(waterGroup);for(const w of waters){const rings=w.geometry.coordinates;const outer=rings[0].map(p=>{const [x,z]=xy(...p);return new THREE.Vector2(x,-z)});const holes=rings.slice(1).map(r=>r.map(p=>{const [x,z]=xy(...p);return new THREE.Vector2(x,-z)}));const shape=new THREE.Shape(outer);shape.holes=holes.map(h=>new THREE.Path(h));const g=new THREE.ShapeGeometry(shape);const p=g.attributes.position;let elevation=Math.min(...rings[0].map(c=>sample(...c)));for(let i=0;i<p.count;i++){const x=p.getX(i),z=-p.getY(i);p.setXYZ(i,x,(sample(lon0+x/(111320*Math.cos(lat0*Math.PI/180)*scale),lat0-z/(111320*scale))-meta.min)*scale*12+.02,z)}g.computeVertexNormals();waterGroup.add(new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:'#329ca9',roughness:.3,metalness:.2,side:THREE.DoubleSide,transparent:true,opacity:.88,depthTest:true})))}}
function densify(seg){const out=[];for(let i=1;i<seg.length;i++){const a=seg[i-1],b=seg[i],dist=Math.hypot((b[0]-a[0])*62000,(b[1]-a[1])*111320),n=Math.max(1,Math.ceil(dist/25));for(let j=0;j<n;j++)out.push([a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n])}out.push(seg[seg.length-1]);return out}
function deformed(seg){if(!state.lab||state.year===0)return seg;return seg.map((p,i)=>{if(i<3||i>seg.length-4)return p;const a=seg[Math.max(0,i-3)],b=seg[Math.min(seg.length-1,i+3)];const dx=(b[0]-a[0])*62000,dz=(b[1]-a[1])*111320,len=Math.hypot(dx,dz)||1;const nx=-dz/len,nz=dx/len;const mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];const curve=((p[0]-mid[0])*62000*nx+(p[1]-mid[1])*111320*nz);const shift=Math.tanh(curve/15)*state.year*.45*state.flow*(.35+state.sed)*Math.sin(i/(seg.length-1)*Math.PI);const next=[p[0]+nx*shift/62000,p[1]+nz*shift/111320];return inCity(next)?next:p})}
function buildRivers(){clear(riverGroup);paths=[];rivers.forEach((r,ri)=>{const selected=state.selected===ri,dim=state.selected>=0&&!selected;for(const raw of r.segments){if(raw.length<2)continue;const seg=densify(raw);const coords=selected?deformed(seg):seg;const pts=coords.map(p=>point(...p,.055));if(pts.length<2)continue;const curve=new THREE.CatmullRomCurve3(pts,false,'centripetal');const radius=selected?.026:.013;const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.min(pts.length*2,2000),radius,5,false),new THREE.MeshStandardMaterial({color:dim?'#70948c':selected?'#67d9e2':'#328d9a',emissive:dim?'#000000':'#176c78',emissiveIntensity:.35,roughness:.4,transparent:dim,opacity:dim?.4:1}));mesh.userData.river=ri;riverGroup.add(mesh);if(!dim)paths.push({curve,len:curve.getLength(),ri});if(selected&&state.lab){const original=new THREE.Line(new THREE.BufferGeometry().setFromPoints(seg.map(p=>point(...p,.045))),new THREE.LineBasicMaterial({color:'#eeb65d'}));riverGroup.add(original)}}});if(particles){world.remove(particles);particles.geometry.dispose();particles.material.dispose()}const tracks=paths.filter(p=>p.len>.12);paths=tracks;const arrows=[];for(let j=0;j<paths.length;j++){const n=Math.max(1,Math.ceil(paths[j].len/(rivers[paths[j].ri].name==='Волга'?1:.55)));for(let k=0;k<n;k++)arrows.push({path:j,phase:k/n})}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([0,0,-1,-.48,0,.6,0,0,.23,.48,0,.6],3));geo.setIndex([0,1,2,0,2,3]);geo.computeVertexNormals();const mat=new THREE.MeshBasicMaterial({color:'#edffff',side:THREE.DoubleSide,transparent:true,opacity:.95,depthTest:false});particles=new THREE.InstancedMesh(geo,mat,arrows.length);particles.userData.arrows=arrows;particles.renderOrder=5;particles.frustumCulled=false;world.add(particles);updateParticles()}
