function updateParticles(){if(!particles||!paths.length)return;const arrows=particles.userData.arrows;for(let i=0;i<arrows.length;i++){const a=arrows[i],path=paths[a.path],u=((a.phase+time*.12*state.flow/Math.max(path.len,.15))%1+1)%1;const p=path.curve.getPoint(THREE.MathUtils.clamp(u,0,1-1e-9));const next=path.curve.getPoint(THREE.MathUtils.clamp(u+.001,0,1));const dx=next.x-p.x,dz=next.z-p.z;arrowDummy.position.set(p.x,p.y+.09,p.z);arrowDummy.rotation.set(0,Math.atan2(-dx,-dz),0);const size=state.selected<0?.13:rivers[path.ri].name==='Волга'?.18:.07;arrowDummy.scale.setScalar(size);arrowDummy.updateMatrix();particles.setMatrixAt(i,arrowDummy.matrix)}particles.instanceMatrix.needsUpdate=true}

function frame(){let center=v3(0,.6,0),span=Math.max(width,depth);if(state.selected>=0){const box=new THREE.Box3();rivers[state.selected].segments.flat().forEach(p=>box.expandByPoint(point(...p)));center=box.getCenter(new THREE.Vector3());const size=box.getSize(new THREE.Vector3());span=Math.max(size.x,size.z,1.5)*1.5}const distance=span/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*Math.max(1,1/camera.aspect)*1.03;center.y*=state.exag/12;controls.target.copy(center);if(state.top){camera.position.copy(center).add(v3(0,distance,.001))}else{camera.position.copy(center).add(v3(span*.15,distance*.64,distance*.82))}controls.update()}
function select(index){if(!Number.isInteger(index)||index< -1||index>=rivers.length)throw Error('Неизвестная река');state.selected=index;state.lab=false;state.year=0;syncLab();document.querySelectorAll('.river').forEach(b=>b.classList.toggle('active',Number(b.dataset.river)===index));const r=rivers[index];$('title').textContent=r?r.name:'Чебоксары';$('subtitle').textContent=r?`${fmt(r.length)} км ${r.name==='Волга'?'вдоль города':'в границах города'}`:'Рельеф, долины и водотоки';$('statLabel').textContent=r?'Длина в городе, км':'Именованных рек';$('riverCount').textContent=r?fmt(r.length):rivers.filter(r=>r.name!=='Безымянные ручьи').length;$('console-title').textContent=r?'Течение в городской долине':'Вода следует рельефу';$('experiment').disabled=!r;buildRivers();frame()}
function syncLab(){document.body.classList.toggle('lab',state.lab);$('lab-controls').hidden=!state.lab;$('experiment').classList.toggle('active',state.lab);$('experiment').textContent=state.lab?'Карта':'Эксперимент';$('mode-label').textContent=state.lab?'УСЛОВНЫЙ ЭКСПЕРИМЕНТ':'НАБЛЮДЕНИЕ';$('year').value=state.year;$('yearValue').textContent=Math.round(state.year)}
function setExag(value){state.exag=value;$('exag').value=value;$('exagValue').textContent=value+'×';world.scale.y=value/12;}
function togglePlay(){state.playing=!state.playing;$('play').textContent=state.playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',state.playing?'Приостановить течение':'Продолжить течение')}
function wire(){rivers.forEach((r,i)=>{const b=document.createElement('button');b.className='river';b.dataset.river=i;const label=document.createElement('span');label.textContent=r.name;const length=document.createElement('small');length.textContent=fmt(r.length)+' км';b.append(label,length);b.onclick=()=>select(i);$('rivers').append(b)});$('all').dataset.river=-1;$('all').onclick=()=>select(-1);$('exag').oninput=e=>setExag(Number(e.target.value));$('flow').oninput=e=>{state.flow=Number(e.target.value);$('flowValue').textContent=state.flow.toFixed(1)+'×';if(state.lab)buildRivers()};$('sed').oninput=e=>{state.sed=Number(e.target.value);$('sedValue').textContent=state.sed.toFixed(1);buildRivers()};$('year').oninput=e=>{state.year=Number(e.target.value);$('yearValue').textContent=Math.round(state.year);buildRivers()};$('play').onclick=togglePlay;$('experiment').onclick=()=>{if(state.selected<0)return;state.lab=!state.lab;state.year=0;syncLab();buildRivers()};$('view3d').onclick=()=>setView(false);$('viewTop').onclick=()=>setView(true);$('reset').onclick=frame;for(const id of ['about','sources'])$(id).onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info')){const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close()}};window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','TEXTAREA'].includes(e.target.tagName)&&!$('info').open){e.preventDefault();togglePlay()}});let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5||e.button!==0)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(riverGroup.children).find(h=>h.object.userData.river!==undefined);if(hit)select(hit.object.userData.river)});$('heightLegend').textContent=`${Math.round(meta.min)}–${Math.round(meta.max)}`}
function setView(top){state.top=top;$('view3d').classList.toggle('active',!top);$('viewTop').classList.toggle('active',top);frame()}
function webMCP(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'list_city_rivers',description:'List the OSM rivers in Cheboksary and the adjacent Volga frontage, with displayed lengths.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected an empty object');return rivers.map(r=>({name:r.name,lengthMeters:r.length}))}},{name:'select_city_river',description:'Select a river on the visible 3D map. Use an exact name from list_city_rivers, or Весь город.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.name!=='string')throw Error('name is required');const i=input.name==='Весь город'?-1:rivers.findIndex(r=>r.name===input.name);if(i<0&&input.name!=='Весь город')throw Error('Unknown river');select(i);return {selected:$('title').textContent}}}]){try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}}
async function start(){try{const responses=await Promise.all(['terrain.json','terrain.bin','rivers.json','boundary.json','water.json','surface-mask.bin'].map(p=>fetch('data/'+p).then(r=>{if(!r.ok)throw Error('Не удалось загрузить '+p);return p.endsWith('.bin')?r.arrayBuffer():r.json()})));[meta,,rivers,boundary,waters]=responses;heights=new Float32Array(responses[1]);surfaceMask=new Uint8Array(responses[5]);if(heights.length!==meta.width*meta.height)throw Error('Неполная сетка высот');const [w,s,e,n]=meta.bounds;lon0=(w+e)/2;lat0=(s+n)/2;width=(e-w)*111320*Math.cos(lat0*Math.PI/180)*scale;depth=(n-s)*111320*scale;initScene();buildTerrain();buildBoundary();buildWater();wire();select(-1);$('loading').hidden=true;webMCP();let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.max(0,Math.min((now-last)/1000,.05));last=now;if(state.playing){time+=dt;if(state.lab){state.year=Math.min(100,state.year+dt*2);$('year').value=state.year;$('yearValue').textContent=Math.round(state.year);if(Math.floor(state.year)!==lastLab){lastLab=Math.floor(state.year);buildRivers()}if(state.year===100)togglePlay()}}updateParticles();controls.update();document.querySelector('.compass b').style.transform='rotate('+(-Math.atan2(camera.position.x-controls.target.x,camera.position.z-controls.target.z))+'rad)';renderer.render(scene,camera)}requestAnimationFrame(animate)}catch(e){$('loading').textContent='Не удалось открыть карту: '+e.message;console.error(e)}}start();
